  static const int OAUTH2_CLIENT_AUTHENTICATION_TYPE_DIGEST = 1;

  /// < Client credentials are sent via request body
  static const int OAUTH2_CLIENT_AUTHENTICATION_TYPE_REQUEST_BODY = 2;
}

